31: function NoActivityHistory() {
32:   return <p className="lbh-label">{noActivityHistory}</p>;
33: }
34: export interface ActivityHistoryListProps {
35:   targetId: string;
36:   entityType: EntityType;
37: }
38: 
39: export const ActivityHistoryList = ({
40:   targetId,
41:   entityType,
42: }: ActivityHistoryListProps): JSX.Element => {
43:   const { data, size, setSize, error } = useActivityHistory(targetId);
44: 
45:   const response = useMemo(() => {
46:     if (!data) return null;
47:     return data[size - 1];
48:   }, [data, size]);
49: 
50:   const { data: referenceData, error: errorReferenceData } = useReferenceData<
51:     | "answers"
52:     | "religion-belief"
53:     | "age-bracket"
54:     | "ethnic-group-a"
55:     | "gender"
56:     | "sexual-orientation"
57:   >({
58:     category: "equality-information",
59:   });
60: 
61:   if (errorReferenceData) {
62:     return (
63:       <ErrorSummary
64:         id="equality-information-error"
65:         title={locale.errors.unexpectedResponse}
66:         description={locale.errors.unexpectedResponseDescription}
67:       />
68:     );
69:   }
70: 
71:   if (error?.response?.status === 404) {
72:     return <NoActivityHistory />;
73:   }
74: 
75:   if (!response || !referenceData) {
76:     return (
77:       <Center>
78:         <Spinner />
79:       </Center>
80:     );
81:   }
82: 
83:   const {
84:     results: activityHistory,
85:     paginationDetails: { nextToken },
86:   } = response;
87: 
88:   return (
89:     <div>
90:       <Table>
91:         <ActivityHistoryHeaders entityType={entityType} />
92:         <Tbody>
93:           {activityHistory.map((activity, index) => {
94:             const { targetType } = activity;
95:             if (targetType === "person") {
96:               return <PersonActivityRecord key={index} personRecord={activity} />;
97:             }
98:             if (targetType === "contactDetails") {
99:               return (
100:                 <ContactDetailsActivityRecord
101:                   key={index}
102:                   contactDetailsRecord={activity}
103:                 />
104:               );
105:             }
106:             if (targetType === "tenure") {
107:               return <TenureActivityRecord key={index} tenureRecord={activity} />;
108:             }
109:             if (targetType === "tenurePerson") {
110:               return (
111:                 <TenurePersonActivityRecord key={index} tenurePersonRecord={activity} />
112:               );
113:             }
114:             if (targetType === "personEqualityInformation") {
115:               return (
116:                 <PersonEqualityInformationActivityRecord
117:                   referenceData={referenceData}
118:                   key={index}
119:                   personEqualityInformationRecord={activity}
120:                 />
121:               );
122:             }
123:             if (targetType === "process") {
124:               return <ProcessActivityRecord key={index} processRecord={activity} />;
125:             }
126:             if (targetType === "cautionaryAlert") {
127:               return (
128:                 <CautionaryAlertActivityRecord
129:                   key={index}
130:                   cautionaryAlertRecord={activity}
131:                 />
132:               );
133:             }
134:             if (targetType === "patchesAndAreas" || targetType === "asset") {
135:               return (
136:                 <>
137:                   <PatchesAndAreasActivityRecord
138:                     key={index}
139:                     patchesAndAreasRecord={activity}
140:                   />
141:                   <AssetActivityRecord key={index} assetRecord={activity} />
142:                 </>
143:               );
144:             }
145:             return null;
146:           })}
147:         </Tbody>
148:       </Table>
149:       <SimplePagination>
150:         {size !== 1 && (
151:           <SimplePaginationButton variant="previous" onClick={() => setSize(size - 1)}>
152:             Previous
153:           </SimplePaginationButton>
154:         )}
155:         {nextToken && (
156:           <SimplePaginationButton variant="next" onClick={() => setSize(size + 1)}>
157:             Next
158:           </SimplePaginationButton>
159:         )}
160:       </SimplePagination>
161:     </div>
162:   );
163: };

