1: import React, { ComponentPropsWithoutRef, useMemo } from "react";
2: 
3: import { Activity, ActivityChangeRecord } from "../../../services/activities";
4: import { ActivityRecordItem } from "../activity-record-item";
5: import { MigratedEntityRecord, UpdatedEntityRecord, formattedDate } from "../utils";
6: 
7: import { locale } from "@services";
8: 
9: const { activities }: any = locale;
10: const { entityCreated, entityEdited, removedLabel } = activities;
11: 
12: interface PersonActivityRecordProps
13:   extends Omit<ComponentPropsWithoutRef<"div">, "children"> {
14:   personRecord: Activity;
15: }
16: 
17: export const PersonActivityRecord = ({
18:   personRecord,
19:   ...props
20: }: PersonActivityRecordProps): JSX.Element | null => {
21:   const {
22:     oldData: oldDataActivity,
23:     newData: newDataActivty,
24:     type,
25:     targetType,
26:   } = personRecord;
27: 
28:   const oldData = useMemo(() => oldDataActivity || {}, [oldDataActivity]);
29:   const newData = useMemo(() => newDataActivty || {}, [newDataActivty]);
30: 
31:   const date = formattedDate(personRecord.createdAt);
32:   const category = entityEdited(personRecord.targetType);
33:   const edittedBy = personRecord.authorDetails.fullName;
34: 
35:   const activityRecord = useMemo(() => {
36:     switch (type) {
37:       case "create":
38:         return <CreatedPersonRecord targetType={targetType} />;
39:       case "delete":
40:         return (
41:           <DeletedPersonRecord
42:             targetType={targetType}
43:             oldData={oldData}
44:             newData={newData}
45:           />
46:         );
47:       case "update":
48:         return (
49:           <UpdatedEntityRecord
50:             targetType={targetType}
51:             oldData={oldData}
52:             newData={newData}
53:           />
54:         );
55:       case "migrate":
56:         return <MigratedEntityRecord targetType={targetType} />;
57:       default:
58:         return null;
59:     }
60:   }, [type, targetType, oldData, newData]);
61: 
62:   return (
63:     <ActivityRecordItem
64:       {...props}
65:       date={date}
66:       category={category}
67:       editDetails={activityRecord}
68:       editedBy={edittedBy}
69:     />
70:   );
71: };
72: 
73: const CreatedPersonRecord = ({ targetType }: any): JSX.Element => (
74:   <p>
75:     <b>{entityCreated(targetType)}</b>
76:   </p>
77: );
78: 
79: const DeletedPersonRecord = ({
80:   targetType,
81:   newData,
82:   oldData,
83: }: ActivityChangeRecord): any => {
84:   const parametersOnTargetType = activities[targetType];
85: 
86:   if (targetType === "person") {
87:     const removedData = Object.keys(oldData).filter((paramName: string) => {
88:       if (oldData[paramName] === newData[paramName]) return;
89:       return oldData[paramName];
90:     });
91: 
92:     return removedData.map((paramName: string, index) => {
93:       if (paramName === "id") return;
94:       return (
95:         <div key={index}>
96:           <p>
97:             <b>{parametersOnTargetType[paramName].field}</b>
98:           </p>
99:           <p>
100:             {removedLabel}{" "}
101:             <b>{parametersOnTargetType[paramName].output(oldData[paramName])}</b>
102:           </p>
103:         </div>
104:       );
105:     });
106:   }
107: };

